<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import NetworkWorkspace from './components/NetworkWorkspace.vue';
import WorkerManager from './components/WorkerManager.vue';
import TaskDetail from './components/TaskDetail.vue';
import {Activity,ArrowDownToLine,ArrowLeft,ArrowRight,ArrowUpRight,Battery,Bell,Check,ChevronRight,ClipboardList,Clock,Compass,FileText,Layers,LayoutDashboard,LogOut,MapPin,Radio,Route as RouteIcon,Search,Send,Settings,ShieldCheck,Video,Wifi,Zap,Users} from 'lucide-vue-next';
import {api,type State,type Task,type Worker} from './api';
const router=useRouter();const workers=ref<Worker[]>([]),detailId=ref('');const detail=computed(()=>state.value.tasks.find(t=>t.id===detailId.value));const showTask=(id:string)=>{detailId.value=id;};const workerName=(id:string)=>workers.value.find(w=>w.username===id)?.displayName||id;const route=useRoute();const state=ref<State>({nodes:[],pipes:[],tasks:[],alerts:[],devices:[],messages:[],events:[],networkSource:"",demo:true});
const token=ref(sessionStorage.getItem('token')||'');const username=ref('admin'),password=ref('PipeDemo2026!');const error=ref(''),notice=ref(''),busy=ref(false),selectedPipe=ref('P01'),selectedTask=ref('T-DEMO01');
const from=ref('J01'),to=ref('J06'),taskName=ref('北区排水支管日常巡检'),message=ref(''),query=ref('');
const preview=ref<{pipes:string[];length:number;method:string}|null>(null);
const nav=[{path:'/',name:'工作总览',icon:LayoutDashboard},{path:'/network',name:'管网与规划',icon:Layers},{path:'/workers',name:'工作人员',icon:Users},{path:'/tasks',name:'巡检任务',icon:ClipboardList},{path:'/alerts',name:'告警中心',icon:Bell},{path:'/devices',name:'设备资产',icon:Radio},{path:'/reports',name:'巡检档案',icon:FileText}];
const title=computed(()=>nav.find(n=>n.path===route.path)?.name||'系统设置');
const status:Record<string,string>={draft:'待审核',approved:'待下发',dispatched:'待进场',running:'巡检中',paused:'已暂停',completed:'待复核',reviewed:'已归档',normal:'状态正常',attention:'关注管段',blocked:'暂停通行'};
const node=(id:string)=>state.value.nodes.find(n=>n.id===id)!;
const active=computed(()=>state.value.tasks.find(t=>t.id===selectedTask.value)||state.value.tasks[0]);
const pipe=computed(()=>state.value.pipes.find(p=>p.id===selectedPipe.value));
const openAlerts=computed(()=>state.value.alerts.filter(a=>!a.ack));
const filtered=computed(()=>state.value.tasks.filter(t=>(t.name+t.id).toLowerCase().includes(query.value.toLowerCase())));
const pipeColor=(id:string,s:string)=>preview.value?.pipes.includes(id)?'#d99544':active.value?.pipes.includes(id)&&route.path==='/'?'#168d82':s==='blocked'?'#8b97a0':s==='attention'?'#d99544':'#70a99e';
let refreshVersion=0;
async function refresh(){if(!token.value)return;const version=++refreshVersion;try{const [next,people]=await Promise.all([api<State>('/state'),api<Worker[]>('/workers')]);if(version!==refreshVersion)return;state.value=next;workers.value=people;error.value='';}catch(e){if(version===refreshVersion)error.value=(e as Error).message;}}
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn();error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function login(){await run(async()=>{const r=await api<{token:string;role:string}>('/auth/login',{username:username.value,password:password.value});if(r.role!=='admin')throw Error('网页工作台请使用管理员账号');sessionStorage.setItem('token',r.token);token.value=r.token;await refresh();});}
function logout(){sessionStorage.removeItem('token');token.value='';}
async function plan(){await run(async()=>{preview.value=await api('/routes/preview',{start:from.value,end:to.value});});}
async function create(){await run(async()=>{const t=await api<Task>('/tasks',{name:taskName.value,start:from.value,end:to.value,worker:'worker',device:'PP-001'});selectedTask.value=t.id;notice.value='任务已建立，审核后即可下发';await refresh();});}
async function action(t:Task,a:string){await run(async()=>{await api('/tasks/'+t.id+'/action',{action:a,note:'管理端人工确认'});notice.value='任务状态已更新';await refresh();});}
async function send(){if(!active.value||!message.value.trim())return;await run(async()=>{await api('/tasks/'+active.value!.id+'/messages',{text:message.value});message.value='';notice.value='消息已发送至作业端';await refresh();});}
async function ack(id:string){await run(async()=>{await api('/alerts/'+id+'/ack',{});await refresh();});}
function exportTask(t:Task){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),task:t,pipes:state.value.pipes.filter(p=>t.pipes.includes(p.id)),messages:state.value.messages.filter(m=>m.task===t.id),demo:state.value.demo},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=t.id+'.json';a.click();URL.revokeObjectURL(u);}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{if(route.path==='/routes')router.replace('/network');window.addEventListener('session-expired',logout);refresh();timer=setInterval(refresh,5000);});onUnmounted(()=>{clearInterval(timer);window.removeEventListener('session-expired',logout);});
</script>

<template>
 <div v-if="!token" class="login-layout"><div class="login-story"><div class="brand"><span class="brand-icon"><Activity :size="26"/></span>管脉探微<span class="brand-version">管网巡检</span></div><div class="login-copy"><span class="eyebrow">SEE BENEATH. ACT WITH CONFIDENCE.</span><h1>看见地下，<br>让每一段巡检<br><em>都有迹可循。</em></h1><p>从片区规划，到现场作业，再到异常复核。<br>连接设备、人员与城市地下管网。</p><p class="project-fullname">管脉探微——城市无压重力流排水管道低前置条件星闪中继巡检机器人</p></div><div class="login-bottom">开源智能硬件 · 星闪中继巡检 <span>01 / CONTROL CENTER</span></div></div><form class="login-card" @submit.prevent="login"><span class="eyebrow">欢迎使用管脉探微</span><h2>进入巡检工作台</h2><p>请使用管理账号登录你的工作空间</p><label>账号<input v-model="username" autocomplete="username" required /></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required /></label><div v-if="error" class="error">{{error}}</div><button class="primary" :disabled="busy">{{busy?'正在连接…':'登录工作台'}}<ArrowRight :size="17"/></button><div class="demo-note"><ShieldCheck :size="17"/><span>管理员登录 · 请妥善保管账号密码<br>统一管理片区、人员、设备与巡检资料。</span></div></form></div>
 <div v-else class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon"><Activity :size="25"/></span><div>管脉探微<small>星闪中继巡检平台</small></div></div><div class="workspace"><div class="workspace-icon">P</div><div>滨河园区 · 示例片区<small><span class="dot"/> 片区运维工作空间</small></div><ChevronRight :size="14"/></div><div class="nav-label">工作空间</div><nav><RouterLink v-for="n in nav" :key="n.path" :to="n.path" :class="{selected:route.path===n.path}"><component :is="n.icon" :size="19"/>{{n.name}}<span v-if="n.path==='/alerts'&&openAlerts.length" class="nav-count">{{openAlerts.length}}</span></RouterLink></nav><div class="sidebar-bottom"><div class="service"><div><span class="dot"/>平台服务正常</div><small>片区巡检 · 协同调度</small></div><RouterLink to="/settings"><Settings :size="18"/>系统设置</RouterLink><button @click="logout"><LogOut :size="18"/>退出登录</button></div></aside>
 <main><header><div class="breadcrumb">工作空间 <ChevronRight :size="14"/><strong>{{title}}</strong></div><div class="header-actions"><span class="local-tag">{{state.demo?'示例片区':'管网档案'}}</span><Bell :size="19"/><span class="avatar">管</span><span>管理人员</span></div></header><div class="page"><div class="page-heading"><div><div class="eyebrow">{{route.path==='/'?'OPERATIONS OVERVIEW':'管脉探微 · 工作空间'}}</div><h1>{{title}}<span v-if="route.path==='/'" class="live-pill"><span class="dot"/>实时同步</span></h1><p>{{route.path==='/'?'连接片区管网、现场设备与每一次巡检任务。':'从可视化管网到任务归档，让现场协作更清晰。'}}</p></div><RouterLink to="/network" class="primary"><span>＋</span> 新建巡检任务</RouterLink></div>
 <div v-if="error" class="error" role="alert">{{error}}</div><div v-if="notice" class="notice" @click="notice=''">{{notice}} <Check :size="16"/></div>
 <div class="metrics" v-if="route.path==='/'"><div class="metric"><div>片区管段总长<Layers :size="18"/></div><strong>{{state.pipes.reduce((s,p)=>s+p.length,0)}}<small>m</small></strong><footer>{{state.pipes.length}}条管段 · {{state.nodes.length}}座检查井</footer></div><div class="metric"><div>正在执行任务<Activity :size="18"/></div><strong>{{state.tasks.filter(t=>t.status==='running').length}}<small>项</small></strong><footer><span class="dot"/>现场作业状态同步</footer></div><div class="metric"><div>待现场执行<ClipboardList :size="18"/></div><strong>{{state.tasks.filter(t=>t.status==='dispatched').length}}<small>项</small></strong><footer>任务已下发至作业人员</footer></div><div class="metric"><div>待处理告警<Bell :size="18"/></div><strong :class="{amber:openAlerts.length}">{{openAlerts.length}}<small>条</small></strong><footer>{{openAlerts.length?'请关注现场异常':'当前暂无待处理告警'}}</footer></div></div>
 <NetworkWorkspace v-if="route.path==='/network'" :state="state" :workers="workers" @refresh="refresh" @created="id=>{selectedTask=id;}"/>
 <div v-if="route.path==='/'" class="overview-network"><NetworkWorkspace :state="state" :workers="workers" compact @refresh="refresh"/><aside class="panel task-focus"><div class="panel-heading"><h3>现场巡检</h3><RouterLink to="/tasks">查看任务 →</RouterLink></div><template v-if="active"><h3>{{active.name}}</h3><p>{{active.start}} → {{active.end}} · {{workerName(active.worker)}}</p><video v-if="active.videoUrl" class="overview-video" :src="active.videoUrl" controls/><div v-else class="video-placeholder"><Video :size="30"/><strong>尚未连接摄像头</strong></div><div class="progress-label"><span>任务进度</span><strong>{{active.progress}}%</strong></div><div class="progress"><i :style="{width:active.progress+'%'}"/></div><div class="mini-stats"><div><Battery :size="17"/>{{state.devices.find(d=>d.id===active.device)?.lastSeen?state.devices.find(d=>d.id===active.device)?.battery+'%':'—'}}<small>设备电量</small></div><div><Wifi :size="17"/>{{state.devices.find(d=>d.id===active.device)?.online?'在线':'离线'}}<small>通信状态</small></div></div><button class="outline" @click="showTask(active.id)">查看作业详情</button></template></aside></div>
 <WorkerManager v-if="route.path==='/workers'" :workers="workers" :state="state" @refresh="refresh" @select-task="showTask"/>
 <TaskDetail v-if="detail" :task="detail" :state="state" :workers="workers" @close="detailId=''" @refresh="refresh"/>
 <section v-if="['/','/tasks','/reports'].includes(route.path)" class="panel task-table"><div class="panel-heading"><div><h3>{{route.path==='/reports'?'巡检资料与任务档案':'巡检任务'}} <span class="counter">{{state.tasks.length}}</span></h3><p>管理端审核下发，作业端确认执行</p></div><div class="search"><Search :size="16"/><input v-model="query" placeholder="搜索任务名称或编号" aria-label="搜索任务"/></div></div><div class="table-scroll"><table><thead><tr><th>任务名称 / 编号</th><th>起止检查井</th><th>作业人员</th><th>进度</th><th>任务状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in filtered" :key="t.id" @click="selectedTask=t.id"><td><strong>{{t.name}}</strong><small>{{t.id}} · {{t.device}}</small></td><td>{{t.start}} <span class="muted">→</span> {{t.end}}</td><td><span class="user-dot">W</span>{{workerName(t.worker)}}</td><td><div class="table-progress"><i :style="{width:t.progress+'%'}"/></div><small>{{t.progress}}%</small></td><td><span class="badge" :class="t.status">{{status[t.status]}}</span></td><td><button class="text-btn" @click.stop="showTask(t.id)">详情</button><button v-if="t.status==='draft'" class="text-btn" @click.stop="action(t,'approve')" :disabled="busy">审核通过</button><button v-if="t.status==='approved'" class="text-btn" @click.stop="action(t,'dispatch')" :disabled="busy">下发任务</button><button v-if="t.status==='completed'" class="text-btn" @click.stop="action(t,'review')" :disabled="busy">复核归档</button><button v-if="t.status==='running'" class="text-btn" @click.stop="action(t,'pause')" :disabled="busy">暂停</button><button class="text-btn" @click.stop="exportTask(t)" title="导出任务资料"><ArrowDownToLine :size="17"/></button></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty">暂无匹配任务</td></tr></tbody></table></div></section>
 <div class="bottom-grid" v-if="route.path==='/'||route.path==='/tasks'"><section class="panel"><div class="panel-heading"><h3>任务消息</h3><Send :size="17"/></div><div class="message-box"><select v-model="selectedTask"><option v-for="t in state.tasks" :key="t.id" :value="t.id">{{t.name}}</option></select><div class="message-history"><div v-for="m in state.messages.filter(m=>m.task===active?.id).slice(0,4)" :key="m.id"><small>{{m.sender==='admin'?'调度中心':workerName(m.sender)}} · {{new Date(m.at).toLocaleString()}}</small><p>{{m.text}}</p><small>{{m.acknowledged?'已确认':'待确认'}}</small></div><p v-if="!state.messages.some(m=>m.task===active?.id)" class="muted">暂无消息</p></div><div class="message-input"><input v-model="message" maxlength="500" placeholder="输入现场提示或任务补充说明" @keyup.enter="send"/><button class="primary" @click="send" :disabled="busy||!message.trim()">发送<Send :size="14"/></button></div></div></section><section class="panel"><div class="panel-heading"><h3>现场作业准则</h3><ShieldCheck :size="18"/></div><div class="principles"><div><span>01</span><div><strong>晴天、低水位，满足现场许可</strong><p>雨天延期，水位异常时暂停并回收设备。</p></div></div><div><span>02</span><div><strong>一条任务，一段清晰记录</strong><p>检查井A至B组织作业，原始资料关联任务编号。</p></div></div><div><span>03</span><div><strong>本地保护优先，作业人员接管</strong><p>失联、卡滞等异常先停车，再确认恢复条件。</p></div></div></div></section></div>
 <section class="panel" v-if="route.path==='/alerts'"><div class="panel-heading"><h3>告警与人工确认</h3><span class="subtle-tag">{{openAlerts.length}} 条待处理</span></div><div class="empty" v-if="!state.alerts.length"><ShieldCheck :size="42"/><h3>当前暂无告警</h3><p>设备异常上报后将在此显示，并同步至作业端。</p></div><article v-for="a in state.alerts" :key="a.id" class="alert-row"><Bell :size="20"/><div><strong>{{a.text}}</strong><p>{{a.task}} · {{new Date(a.at).toLocaleString()}}</p></div><span class="badge">{{a.ack?'已确认':'待确认'}}</span><button v-if="!a.ack" class="outline" @click="ack(a.id)">确认收到</button></article></section>
 <div class="device-grid" v-if="route.path==='/devices'"><section v-for="d in state.devices" :key="d.id" class="panel device-card"><div class="device-art"><Radio :size="60"/><span>{{d.id}}</span></div><div class="form-body"><h2>{{d.name}}</h2><p class="muted">BearPi-Hi3863 · 分节控制节点</p><span class="badge">{{d.online?'在线':'离线'}}</span><div class="device-values"><span>剩余电量<strong>{{d.lastSeen?d.battery+'%':'—'}}</strong></span><span>参考里程<strong>{{d.lastSeen?d.distance.toFixed(1)+'m':'—'}}</strong></span><span>舱内温度<strong>{{d.lastSeen?d.temperature+'℃':'—'}}</strong></span></div><p class="hint">最后上报：{{d.lastSeen?new Date(d.lastSeen).toLocaleString():'暂无上报'}}</p></div></section></div>
 <section class="panel settings" v-if="route.path==='/settings'"><h2>连接与系统信息</h2><p>管理端与作业端共享管网、任务、人员和设备资料。</p><div class="setting-row"><span>后端服务</span><code>Spring Boot 3.3.5 / Java 17</code></div><div class="setting-row"><span>设备控制板</span><code>BearPi-Hi3863</code></div><div class="setting-row"><span>数据模式</span><code>H2关系数据库 · 本地持久化</code></div><div class="setting-row"><span>现场作业端</span><code>鸿蒙现场作业端</code></div><div class="hint">巡检路线依据当前管网和通行条件计算。管网资料支持JSON与GeoJSON导入。</div></section>
 <footer class="page-footer"><span>管脉探微 / 让每一段管道，有据可查。</span><span>管网巡检 · 作业管理</span></footer></div></main></div>
</template>
